                WHEN word_glossary.source = 'err'      THEN 'oxford+err'
                WHEN word_glossary.source = 'miss'     THEN 'oxford'
                ELSE word_glossary.source
              END
WHERE (word_glossary.ipa IS NULL OR word_glossary.audio_src IS NULL
