  ('recovery', 'sự lấy lại được, sự tìm lại được (vật đã mất...); sự đòi lại được (món nợ...); sự bình phục, sự khỏi bệnh', 'danh từ', '/rɪˈkʌvəri/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recov/recovery__us_1.mp3'),
  ('seal', '(động vật học) chó biển; (như) sealskin* nội động từ; săn chó biển* danh từ', 'danh từ', '/siːl/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sea/seal_/seal__us_1.mp3'),
  ('tube', 'ống; săm (ô tô...) ((cũng) inner tube); tàu điện ngầm', 'danh từ', '/tuːb/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tub/tube_/tube__us_1.mp3'),
  ('tower', 'tháp; đồn luỹ, pháo đài; là người có đủ sức để bảo vệ cho ai* nội động từ', 'danh từ', '/ˈtaʊər/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tow/tower/tower__us_1.mp3'),
  ('characterize', 'biểu thị đặc điểm, mô tả đặc điểm; định rõ đặc điểm', 'ngoại động từ', '/ˈkærəktəraɪz/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chara/characterize__us_1.mp3'),
  ('exact', 'chính xác, đúng, đúng dắn; tống (tiền...); bắt phải nộp, bắt phải đóng, bóp nặn (thuế...); đòi hỏi', 'tính từ', '/ɪɡˈzækt/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exa/exact/exact__us_1.mp3'),
  ('spin', 'sự quay tròn, sự xoay tròn; (hàng không) sự vừa đâm xuống vừa quay tròn; sự đi chơi; cuộc đi chơi ngắn', 'danh từ', '/spɪn/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spi/spin_/spin__us_1.mp3'),
  ('operator', 'người thợ máy; người sử dụng máy móc; người coi tổng đài (dây nói); (y học) người mổ', 'danh từ', '/ˈɑːpəreɪtər/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ope/opera/operator__us_1.mp3'),
  ('infant', 'đứa bé còn ãm ngửa, đứa bé (dưới 7 tuổi); (pháp lý) người vị thành niên; (từ Mỹ', 'danh từ', '/ˈɪnfənt/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inf/infan/infant__us_1.mp3')
